    dp = [[-1] * n for _ in range(n)]

    def can_win(l, r):
        if dp[l][r] != -1:
            return dp[l][r]

        # Base case: if the substring is of length 1, the current player wins
        if l == r:
            dp[l][r] = True
            return True

