                        dp[l][r] = True
                        return True

        # If no winning move is found, the current player loses
        dp[l][r] = False
        return False

    # Determine the winner for each k
    for k in range(n):
        if can_win(k, k):
            winners.append("Ann")
        else:
            winners.append("Mike")

    return winners

